CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('customer','driver','admin')),approved BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS vehicles(id BIGSERIAL PRIMARY KEY,driver_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,category TEXT NOT NULL CHECK(category IN ('Comfort','Business','VIP')),model TEXT NOT NULL,model_year INTEGER,photo_url TEXT,approved BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bookings(id BIGSERIAL PRIMARY KEY,customer_id BIGINT NOT NULL REFERENCES users(id),pickup TEXT NOT NULL,destination TEXT NOT NULL,pickup_at TIMESTAMPTZ,category TEXT NOT NULL CHECK(category IN ('Comfort','Business','VIP')),notes TEXT,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','accepted','completed','cancelled')),accepted_offer_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS offers(id BIGSERIAL PRIMARY KEY,booking_id BIGINT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,driver_id BIGINT NOT NULL REFERENCES users(id),vehicle_id BIGINT REFERENCES vehicles(id),price_sar NUMERIC(10,2) NOT NULL CHECK(price_sar>0),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(booking_id,driver_id));
ALTER TABLE bookings DROP CONSTRAINT IF EXISTS bookings_accepted_offer_id_fkey;
ALTER TABLE bookings ADD CONSTRAINT bookings_accepted_offer_id_fkey FOREIGN KEY(accepted_offer_id) REFERENCES offers(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS messages(id BIGSERIAL PRIMARY KEY,booking_id BIGINT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES users(id),body TEXT NOT NULL CHECK(char_length(body) BETWEEN 1 AND 2000),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS app_settings(id INTEGER PRIMARY KEY DEFAULT 1 CHECK(id=1),offers_enabled BOOLEAN NOT NULL DEFAULT TRUE,pricing_mode TEXT NOT NULL DEFAULT 'driver_offers' CHECK(pricing_mode IN ('driver_offers','admin_fixed','both')),comfort_price NUMERIC(10,2) NOT NULL DEFAULT 200,business_price NUMERIC(10,2) NOT NULL DEFAULT 350,vip_price NUMERIC(10,2) NOT NULL DEFAULT 500,show_model_year BOOLEAN NOT NULL DEFAULT FALSE);
INSERT INTO app_settings(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
